const english=document.documentElement.lang==='en';const assetBase=english?'../assets/':'assets/';
let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;try{reduced=localStorage.getItem('pa-motion')==='off'||reduced}catch{}window.paMotion=!reduced;document.body.classList.toggle('no-motion',reduced);if(!reduced)document.body.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));const menu=document.getElementById('menu'),toggle=document.querySelector('.menu-toggle');toggle.addEventListener('click',()=>{menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',String(!menu.hidden));toggle.textContent=menu.hidden?'☰':'×'});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){menu.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.textContent='☰';toggle.focus()}});document.addEventListener('click',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!toggle.contains(e.target)){menu.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.textContent='☰'}});const motion=document.getElementById('motion');function label(){motion.textContent=(english?'Motion: ':'Анимация: ')+(window.paMotion?(english?'on':'вкл.'):(english?'off':'выкл.'))}label();motion.addEventListener('click',()=>{window.paMotion=!window.paMotion;document.body.classList.toggle('no-motion',!window.paMotion);try{localStorage.setItem('pa-motion',window.paMotion?'on':'off')}catch{}label()});const repos=document.getElementById('repos');if(repos)fetch(assetBase+'repos.json').then(r=>r.json()).then(data=>{data.forEach(r=>{const a=document.createElement('a');a.href=r.url;a.target='_blank';a.rel='noopener';a.textContent=r.name;const s=document.createElement('span');s.textContent=(r.language||'CODE')+' ↗';a.append(s);repos.append(a)})}).catch(()=>{repos.textContent=english?'Public projects are available via the profile link below.':'Открытые проекты доступны по ссылке на профиль ниже.'});

document.querySelectorAll(".language-switch a").forEach(a=>{a.addEventListener("click",()=>{if(location.hash)a.href=a.href.split("#")[0]+location.hash;try{localStorage.setItem("pa-language",a.lang)}catch{}})});
